#include "forge_cuda.h"
#include <cuda_runtime.h>
#include <vector>
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <algorithm>
int main(){cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);for(size_t tk:{128,512,1024,2048,4096})for(size_t tq:{1,8,32,128}){size_t bs=16,blocks=(tk+bs-1)/bs;std::vector<uint32_t>table(blocks);for(size_t i=0;i<blocks;i++)table[i]=blocks-i-1;std::vector<float>q(tq*896),kv(blocks*bs*128);for(size_t i=0;i<q.size();i++)q[i]=((int)(i%31)-15)*.01f;for(size_t i=0;i<kv.size();i++)kv[i]=((int)(i%37)-18)*.02f;float *dq,*dk,*dv,*out;uint32_t*dt;cudaMalloc(&dq,q.size()*4);cudaMalloc(&dk,kv.size()*4);cudaMalloc(&dv,kv.size()*4);cudaMalloc(&out,q.size()*4);cudaMalloc(&dt,table.size()*4);cudaMemcpy(dq,q.data(),q.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(dk,kv.data(),kv.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(dv,kv.data(),kv.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(dt,table.data(),table.size()*4,cudaMemcpyHostToDevice);std::vector<float>ref(q.size()),got(q.size());float times[2];for(int side=0;side<2;side++){setenv("FORGE_PREFILL_ATTN_BLOCK",side?"1":"0",1);auto call=[&](){return forge_cuda_paged_gqa_attn_f32(tq,tk,14,2,64,.125f,dq,896,dk,dv,dt,blocks,bs,blocks,1,0,128,out,1,tk-tq);};for(int i=0;i<5;i++)if(call()!=FORGE_CUDA_OK)return 2;std::vector<float>trials;for(int r=0;r<3;r++){cudaEventRecord(a,cudaStreamPerThread);for(int i=0;i<20;i++)if(call()!=FORGE_CUDA_OK)return 2;cudaEventRecord(b,cudaStreamPerThread);cudaEventSynchronize(b);float ms;cudaEventElapsedTime(&ms,a,b);trials.push_back(ms/20);}std::sort(trials.begin(),trials.end());times[side]=trials[1];cudaMemcpy((side?got:ref).data(),out,q.size()*4,cudaMemcpyDeviceToHost);}float err=0;for(size_t i=0;i<got.size();i++){err=std::max(err,std::abs(got[i]-ref[i]));if(!std::isfinite(got[i])||std::abs(got[i]-ref[i])>1e-4f+1e-3f*std::abs(ref[i]))return 3;}printf("{\"tq\":%zu,\"tk\":%zu,\"warp_ms\":%.6f,\"block_ms\":%.6f,\"max_abs_error\":%.8f}\n",tq,tk,times[0],times[1],err);cudaFree(dq);cudaFree(dk);cudaFree(dv);cudaFree(dt);cudaFree(out);}cudaEventDestroy(a);cudaEventDestroy(b);}
